-- CTR: meta de cama hospitalaria eléctrica y hospital bed.
-- El JSON es el de src/data/familia-seo.ts (landings-cms.test.ts).

UPDATE public.landings
   SET contenido_es = $ime_landing${"name":"Cama hospitalaria eléctrica","title":"Cama hospitalaria eléctrica para clínicas de Colombia | I-ME","description":"Cama hospitalaria eléctrica en Colombia. Compare los modelos publicados, incluida la manual, y pida cotización para el servicio.","intro":"La cama hospitalaria se define por el servicio, el personal y el recorrido del área. La cama eléctrica hospitalaria cambia de posición con motores; la manual, con manivelas. Las dos se cotizan por referencia, no como un mueble genérico.","body":["En el catálogo activo están la cama eléctrica Advanced B-1000 Pro, la B-2000 Plus y la Saikang V6K, y la cama hospitalaria manual Advanced B-2000. Las funciones y medidas de cada una están en su página; no se trasladan de un modelo a otro.","Esta familia también reúne camillas, carros y mesas del mismo entorno clínico. Las camillas de traslado están en emergencias, y las camas obstétricas en neonatología. Para cotizar, indique el espacio útil, las puertas y el uso previsto."],"faq":[{"q":"¿Qué diferencia una cama eléctrica hospitalaria de una manual?","a":"La eléctrica ajusta la posición con motores y la manual con manivelas. Cuál conviene depende del servicio, del personal y del espacio. La configuración de cada referencia se confirma en su página y en la cotización."},{"q":"¿Qué medidas debo enviar?","a":"Espacio útil, puertas, ascensores, recorridos y restricciones del área, además del uso previsto."}]}$ime_landing$::jsonb,
       contenido_en = $ime_landing${"name":"Hospital bed","title":"Hospital bed for clinics in Colombia | I-ME","description":"Hospital bed in Colombia. Compare electric and manual models in the catalog, then request a quote for the ward.","intro":"A hospital bed in Colombia is chosen for the ward, the staff and the route through the building. An electric hospital bed changes position with motors; a manual bed uses cranks. Both are quoted by reference, not as generic furniture.","body":["Active electric hospital beds include the Advanced B-1000 Pro, the B-2000 Plus and the Saikang V6K. The Advanced B-2000 is a manual hospital bed. Functions and dimensions stay on each product page; they are not copied from one model to another.","The same family also lists stretchers, carts and tables used on those wards. Transfer stretchers are in the emergency family, and obstetric beds are with neonatology. When you request a quote, send usable space, doors and the intended service."],"faq":[{"q":"How does an electric hospital bed differ from a manual one?","a":"An electric bed changes position with motors; a manual bed uses cranks. Which one fits depends on the service, the staff and the room. Each reference’s configuration is confirmed on its page and in the quote."},{"q":"Which measurements should I send?","a":"Usable space, doors, elevators, routes and area restrictions, plus intended use."}]}$ime_landing$::jsonb,
       version = version + 1,
       publicado_at = NOW()
 WHERE tipo = 'familia' AND clave = 'mobiliario';

INSERT INTO public.landings_historial (landing_id, version, contenido_es, contenido_en)
SELECT id, version, contenido_es, contenido_en
FROM public.landings
WHERE tipo = 'familia' AND clave = 'mobiliario'
ON CONFLICT (landing_id, version) DO NOTHING;
